# frozen_string_literal: true

# The Rust port of `lib/textkit/`, generated by everything-rust: the same module functions, each
# calling the Rust library through Fiddle. Load it in place of the original files.
# Regenerate with `everything-rust refresh`.

require "fiddle"
require "json"

module EverythingRustCodec
  module_function

  def enc(v)
    case v
    when Float
      return { "$num" => "NaN" } if v.nan?
      return { "$num" => v.positive? ? "Infinity" : "-Infinity" } if v.infinite?
      return { "$num" => "-0" } if v.zero? && (1.0 / v).negative?

      v
    when Integer, String, true, false, nil then v
    when Symbol then { "$sym" => v.to_s }
    when Array then v.map { |x| enc(x) }
    when Hash
      if v.keys.all? { |k| k.is_a?(String) }
        v.transform_values { |x| enc(x) }
      else
        { "$hash" => v.map { |k, x| [enc(k), enc(x)] } }
      end
    else
      { "$object" => v.class.name, "value" => v.respond_to?(:to_h) ? enc(v.to_h) : v.inspect }
    end
  end

  def dec(v)
    case v
    when Array then v.map { |x| dec(x) }
    when Hash
      if v.size == 1 && v.key?("$num")
        { "NaN" => Float::NAN, "Infinity" => Float::INFINITY, "-Infinity" => -Float::INFINITY, "-0" => -0.0 }.fetch(v["$num"])
      elsif v.size == 1 && v.key?("$undefined")
        nil
      elsif v.size == 1 && v.key?("$sym")
        v["$sym"].to_sym
      elsif v.size == 1 && v.key?("$hash")
        v["$hash"].to_h { |k, x| [dec(k), dec(x)] }
      else
        v.transform_values { |x| dec(x) }
      end
    else v
    end
  end
end

module EverythingRustNativeTextkitRs
  names = %w[libtextkit_rs.so libtextkit_rs.dylib textkit_rs.dll]
  path = names.map { |n| File.expand_path("../target/release/#{n}", __dir__) }.find { |p| File.exist?(p) }
  raise LoadError, "build the Rust library first (everything-rust build)" unless path

  LIB = Fiddle.dlopen(path)
  CALL = Fiddle::Function.new(LIB["everything_rust_call"], [Fiddle::TYPE_VOIDP, Fiddle::TYPE_VOIDP], Fiddle::TYPE_VOIDP)
  FREE = Fiddle::Function.new(LIB["everything_rust_free"], [Fiddle::TYPE_VOIDP], Fiddle::TYPE_VOID)

  def self.call(name, args)
    answer_ptr = CALL.call(Fiddle::Pointer["#{name}\0"], Fiddle::Pointer["#{JSON.generate(EverythingRustCodec.enc(args))}\0"])
    text = answer_ptr.to_s.force_encoding(Encoding::UTF_8)
    FREE.call(answer_ptr)
    answer = JSON.parse(text)
    return EverythingRustCodec.dec(answer["ok"]) if answer.key?("ok")

    message = answer["error"] || "Rust panic: #{answer["panic"]}"
    type, rest = message.split(": ", 2)
    klass = rest && type.match?(/\A[A-Z]\w*(::[A-Z]\w*)*\z/) ? (Object.const_get(type) rescue nil) : nil
    raise klass, rest if klass.is_a?(Class) && klass <= Exception

    raise message
  end
end

module EverythingRustShadow
  MODE = ENV.fetch("EVERYTHING_RUST_MODE", "shadow")
  @calls = 0
  @mismatches = 0

  class << self
    attr_reader :calls, :mismatches

    def compare(name, expected, actual)
      @calls += 1
      return if JSON.generate(EverythingRustCodec.enc(expected)) == JSON.generate(EverythingRustCodec.enc(actual))

      @mismatches += 1
      warn "[everything-rust] mismatch in #{name}: expected #{expected.inspect}, got #{actual.inspect}" if @mismatches <= 10
    end
  end
end

Textkit::Nums.singleton_class.prepend(Module.new do
               def page_count(total, per_page = 10)
                 return EverythingRustNativeTextkitRs.call("page_count", [total, per_page]) if EverythingRustShadow::MODE == "new"

                 expected = super
                 unless EverythingRustShadow::MODE == "old"
                   actual = begin
        EverythingRustNativeTextkitRs.call("page_count", [total, per_page])
                   rescue StandardError => e
        e
      end
                   EverythingRustShadow.compare("Textkit::Nums.page_count", expected, actual)
    end
                 expected
  end
end)

